const search=document.querySelector('#guide-search');const cards=[...document.querySelectorAll('.chapter')];const filters=[...document.querySelectorAll('.guide-filter')];let filter='all';function render(){const q=(search?.value||'').trim().toLowerCase();cards.forEach(card=>{const kind=card.dataset.kind||'';const text=card.dataset.search||'';card.hidden=(filter!=='all'&&!kind.includes(filter))||(q&&!text.includes(q)&&!card.textContent.toLowerCase().includes(q))})}filters.forEach(button=>button.addEventListener('click',()=>{filters.forEach(item=>item.classList.remove('active'));button.classList.add('active');filter=button.dataset.filter;render()}));search?.addEventListener('input',render);
